import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs));
}

"use client";

import * as React from "react";
import { motion, useSpring } from "framer-motion";
import { IconArrowRight, IconSparkles } from "@tabler/icons-react";
import { cn } from "@/lib/utils";

export interface PromptSuggestion {
  id: string;
  title: string;
  hint?: string;
  /** Optional icon ReactNode (Tabler / lucide / svg). */
  icon?: React.ReactNode;
}

export interface MagneticPromptSuggestionsProps {
  suggestions: PromptSuggestion[];
  onSelect?: (suggestion: PromptSuggestion) => void;
  /** Pixel radius around the card centre that triggers the pull. */
  radius?: number;
  /** Higher number → less movement (default 3). */
  dampening?: number;
  /** Optional eyebrow / heading shown above the rail. */
  heading?: string;
  className?: string;
}

const DEFAULT_SUGGESTIONS: PromptSuggestion[] = [
  {
    id: "1",
    title: "Brainstorm a launch tweet",
    hint: "Punchy, dev-leaning, ≤ 240 chars",
    icon: <IconSparkles size={16} stroke={2} />,
  },
  {
    id: "2",
    title: "Refactor this React hook",
    hint: "Keep types, drop the deps array",
    icon: <IconSparkles size={16} stroke={2} />,
  },
  {
    id: "3",
    title: "Plan a 3-day Tokyo trip",
    hint: "Coffee + design studios focus",
    icon: <IconSparkles size={16} stroke={2} />,
  },
  {
    id: "4",
    title: "Review my landing copy",
    hint: "Brutally honest, founder voice",
    icon: <IconSparkles size={16} stroke={2} />,
  },
];

/**
 * MagneticPromptSuggestions
 *
 * A horizontal rail of prompt cards that elastically pull toward the cursor
 * before the user clicks — building tactile, physical anticipation.
 *
 * Magnetism rules:
 *  - Track pointer relative to each card's center on `pointerMove`.
 *  - Clamp the magnetic radius (default 100px). Outside → snap back to 0.
 *  - Feed (dx / dampening, dy / dampening) into `useSpring` x/y values.
 *  - Animation runs strictly on transform.
 */
export function MagneticPromptSuggestions({
  suggestions = DEFAULT_SUGGESTIONS,
  onSelect,
  radius = 100,
  dampening = 3,
  heading,
  className,
}: MagneticPromptSuggestionsProps) {
  return (
    <div className={cn("w-full", className)}>
      {heading && (
        <div className="mb-3 text-[12.5px] font-medium tracking-tight text-[var(--muted-foreground)]">
          {heading}
        </div>
      )}
      <div
        className={cn(
          // Responsive grid — no scrollbars, no horizontal rail. Cards
          // wrap naturally and fill available width.
          "grid w-full grid-cols-1 gap-3 sm:grid-cols-2"
        )}
      >
        {suggestions.map((s) => (
          <MagneticCard
            key={s.id}
            suggestion={s}
            radius={radius}
            dampening={dampening}
            onSelect={onSelect}
          />
        ))}
      </div>
    </div>
  );
}

/* ───────────────────────── Single magnetic card ───────────────────────── */

function MagneticCard({
  suggestion,
  radius,
  dampening,
  onSelect,
}: {
  suggestion: PromptSuggestion;
  radius: number;
  dampening: number;
  onSelect?: (s: PromptSuggestion) => void;
}) {
  const ref = React.useRef<HTMLButtonElement>(null);
  // Card body uses a softer, slightly heavier spring — feels weighty.
  const x = useSpring(0, { stiffness: 180, damping: 18, mass: 0.55 });
  const y = useSpring(0, { stiffness: 180, damping: 18, mass: 0.55 });
  // Inner content (icon, title) leads the body with a snappier spring so
  // it visually "pulls" the cursor through the card.
  const ix = useSpring(0, { stiffness: 260, damping: 20, mass: 0.4 });
  const iy = useSpring(0, { stiffness: 260, damping: 20, mass: 0.4 });
  // Cursor-relative spotlight (CSS vars) — adds a subtle chili wash.
  const [hover, setHover] = React.useState(false);

  function handleMove(e: React.PointerEvent<HTMLButtonElement>) {
    const el = ref.current;
    if (!el) return;
    const r = el.getBoundingClientRect();
    const cx = r.left + r.width / 2;
    const cy = r.top + r.height / 2;
    const dx = e.clientX - cx;
    const dy = e.clientY - cy;
    const dist = Math.hypot(dx, dy);

    // Update spotlight CSS vars regardless of magnetic radius.
    el.style.setProperty("--mx", `${e.clientX - r.left}px`);
    el.style.setProperty("--my", `${e.clientY - r.top}px`);

    if (dist > radius) {
      x.set(0);
      y.set(0);
      ix.set(0);
      iy.set(0);
      return;
    }
    // Soft falloff near the edge of the magnetic zone (ease-out cubic).
    const t = 1 - Math.min(1, dist / radius);
    const falloff = 0.55 + 0.45 * (t * t);
    x.set((dx / dampening) * falloff);
    y.set((dy / dampening) * falloff);
    ix.set((dx / (dampening * 0.55)) * falloff);
    iy.set((dy / (dampening * 0.55)) * falloff);
  }

  function reset() {
    x.set(0);
    y.set(0);
    ix.set(0);
    iy.set(0);
    setHover(false);
  }

  return (
    <motion.button
      ref={ref}
      type="button"
      onPointerEnter={() => setHover(true)}
      onPointerMove={handleMove}
      onPointerLeave={reset}
      onPointerCancel={reset}
      onBlur={reset}
      onClick={() => onSelect?.(suggestion)}
      style={{ x, y, willChange: "transform" }}
      className={cn(
        "group relative flex w-full min-w-0 flex-col gap-2 overflow-hidden rounded-2xl p-4 text-left",
        "border border-[var(--border)] bg-[var(--surface)] outline-none",
        "shadow-[0_0_0_1px_rgba(0,0,0,.03),0_2px_4px_rgba(0,0,0,.05),0_12px_24px_rgba(0,0,0,.05)]",
        "dark:shadow-none",
        "transition-colors duration-300 hover:border-[var(--border-strong)]",
        "focus-visible:ring-2 focus-visible:ring-chili-500/50"
      )}
      aria-label={suggestion.title}
    >
      {/* Cursor-following chili wash (CSS-var driven, no React re-render). */}
      <span
        aria-hidden
        className="pointer-events-none absolute inset-0 opacity-0 transition-opacity duration-300 group-hover:opacity-100"
        style={{
          background:
            "radial-gradient(220px circle at var(--mx, 50%) var(--my, 50%), rgba(205,28,24,0.10), transparent 60%)",
        }}
      />
      <motion.div
        style={{ x: ix, y: iy, willChange: "transform" }}
        className="relative flex items-center justify-between"
      >
        <span className="grid h-7 w-7 place-items-center rounded-lg bg-chili-500/10 text-chili-500">
          {suggestion.icon ?? <IconSparkles size={16} stroke={2} />}
        </span>
        <span className="grid h-7 w-7 place-items-center rounded-full text-[var(--muted-foreground)] opacity-0 transition-opacity duration-200 group-hover:opacity-100 group-focus-visible:opacity-100">
          <IconArrowRight
            size={14}
            stroke={2}
            className={cn(
              "transition-transform duration-300",
              hover && "translate-x-0.5 text-chili-500"
            )}
          />
        </span>
      </motion.div>

      <motion.span
        style={{ x: ix, y: iy, willChange: "transform" }}
        className="relative block text-[13.5px] font-semibold leading-snug tracking-tight text-[var(--foreground)]"
      >
        {suggestion.title}
      </motion.span>
      {suggestion.hint && (
        <motion.span
          style={{ x: ix, y: iy, willChange: "transform" }}
          className="relative block text-[12px] leading-snug text-[var(--muted-foreground)]"
        >
          {suggestion.hint}
        </motion.span>
      )}
    </motion.button>
  );
}
